import { screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../tests/utils";
import { ConversationEventType, type ConversationEvent, type EventMetadata } from "../types";
import { MemorySection } from "./MemorySection";

vi.mock("./MemoryDetails", () => ({
  SlotsDetails: () => <div data-testid="slots-details" />,
}));

vi.mock("../Placeholder", () => ({
  NoData: ({ shortLabel, longLabel }: { shortLabel?: string; longLabel?: string }) => (
    <div data-testid="no-data" data-short-label={shortLabel} data-long-label={longLabel} />
  ),
}));

vi.mock("../components/InspectorViewHeader", () => ({
  InspectorViewHeader: ({
    title,
    showViewSwitcher,
  }: {
    title: string;
    showViewSwitcher?: boolean;
  }) => (
    <div
      data-testid="inspector-view-header"
      data-title={title}
      data-show-view-switcher={String(showViewSwitcher)}
    />
  ),
}));

vi.mock("../components/ScrollFadeArea", () => ({
  ScrollFadeArea: ({ children }: { children: React.ReactNode }) => (
    <div data-testid="scroll-fade-area">{children}</div>
  ),
}));

function makeSlotEvent(id: string): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id,
    conversationEventType: ConversationEventType.Slot,
    flowId: "",
    timestamp: "2024-01-01T12:00:00Z",
    originalTimestamp: 0,
    actionText: "",
    name: "my_slot",
    slotValue: "value",
    stepId: "",
    metadata: {} as EventMetadata,
  };
}

describe("MemorySection", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("renders the Memory header", () => {
    renderWithProviders(<MemorySection />, {
      initialStoreState: { slotRelatedEvents: [] },
    });
    const header = screen.getByTestId("inspector-view-header");
    expect(header.dataset.title).toBe("Memory");
  });

  it("renders NoData placeholder with Memory labels when there are no slot events", () => {
    renderWithProviders(<MemorySection />, {
      initialStoreState: { slotRelatedEvents: [] },
    });
    const placeholder = screen.getByTestId("no-data");
    expect(placeholder.dataset.shortLabel).toBe("Memory");
    expect(placeholder.dataset.longLabel).toBe("Memory will be shown here.");
    expect(screen.queryByTestId("slots-details")).not.toBeInTheDocument();
  });

  it("renders SlotsDetails when there are slot events", () => {
    renderWithProviders(<MemorySection />, {
      initialStoreState: { slotRelatedEvents: [makeSlotEvent("ev-1")] },
    });
    expect(screen.getByTestId("slots-details")).toBeInTheDocument();
    expect(screen.queryByTestId("no-data")).not.toBeInTheDocument();
  });

  it("forwards showViewSwitcher prop to InspectorViewHeader", () => {
    renderWithProviders(<MemorySection showViewSwitcher={false} />, {
      initialStoreState: { slotRelatedEvents: [] },
    });
    const header = screen.getByTestId("inspector-view-header");
    expect(header.dataset.showViewSwitcher).toBe("false");
  });
});
